on conflict (id) do update set name=excluded.name, search_name=excluded.search_name, equipment=excluded.equipment, catalog_exercise_id=excluded.catalog_exercise_id, thumbnail_url=excluded.thumbnail_url, animation_url=excluded.animation_url, attribution=excluded.attribution, source_revision=excluded.source_revision;

